        names: [
            "DOCK_CONTEXT_KEY",
            "DockBackgroundToggle",
            // The ONE dock control (folds the
            // retired DockIconButton + DockTabButton onto a shape axis).
            "DockControl",
            // The thin controlled face-swap core.
            "DockCrossfade",
            "DockLayer",
            "DockLayerGroup",
            // The orientation+layout-aware divider primitive.
            "DockSeparator",
            // The ONE overlay trigger (folds the
            // retired DockSelectTrigger/DockDropdownTrigger/DockPopoverTrigger onto the
            // shared `.dock-trigger` recipe).
            "DockTrigger",
            "GlassDock",
            // The dock-as-native-dynamic-search-bar seam.
            "useDockSearch",
            "provideDockContext",
            "useDockContext",
            "useOptionalDockContext",
        ],
    },
] as const;

describe("public runtime surface", () => {
    it("keeps the package subpath cut exact", () => {
        const manifest = JSON.parse(readFileSync("package.json", "utf8"));
        expect(manifest.exports).toHaveProperty("./metric");
        expect(manifest.typesVersions["*"]).toHaveProperty("metric");
        for (const retired of [
            // [2026-08-09 · BK #66 CLOSE · RT-65-C] the batched export cut's own falsifiers:
            // the two keys it RETIRED must be gone from both maps, or the "clean
            // break, no alias" claim is unproven.
            "dropdown-menu",
            "forms",
            "notification",
            "color-swatch",
            "focus-scope",
            "spa-view",
            "icon-tooltip",
            "icon-chip",
            "metric-badge",
            "metric-cell",
            "metric-stack",
            // [2026-08-25 · BK #42 W-SEARCH] `search` — the POSITIVE proof of this
            // unit's cut, and the only proof left: the `subpathRuntimeExports` row that
            // used to assert `useFuzzySearch` behind `./search` is struck with the door
            // it read, so absence is now the whole assertion. Both maps, because a key
            // surviving in `typesVersions` alone is a type-only ghost door that
            // resolves at editor time and 404s at runtime.
            "search",
        ]) {
            expect(manifest.exports).not.toHaveProperty(`./${retired}`);
            expect(manifest.typesVersions["*"]).not.toHaveProperty(retired);
        }
    });

    it("keeps the exact root runtime surface", () => {
        expect(Object.keys(Glass).sort()).toEqual([...rootRuntimeExports].sort());
    });

    it("keeps the Blob renderer implementation private", () => {
        expect(BlobSurface).not.toHaveProperty("useMetaballRenderer");
    });

    it("names every type its published signatures spend", () => {
        // The runtime half is trivial; the assertion is the annotations, which only
        // typecheck while the doors are open (`vue-tsc -p tsconfig.test.json`).
        const source: FourierSource = "elliptic";
        const status: RendererStatus = {
            phase: "ready",
            engine: "webgpu",
            adapter: "probe",
        };
        const backend: GpuBackend = "webgpu";
        expect([source, status.phase, backend]).toEqual(["elliptic", "ready", "webgpu"]);
    });

    it.each(subpathRuntimeExports)(
        "exports $subpath subpath symbol $name",
        ({ surface, name }) => {
            expect(surface).toHaveProperty(name);
        },
    );

    it.each(retiredSubpathRuntimeMembers)(
        "does not export retired $subpath member $name",
        ({ surface, name }) => {
            expect(surface).not.toHaveProperty(name);
        },
    );

    it.each(exactSubpathRuntimeSurfaces)(
        "keeps exact $subpath runtime surface",
        ({ surface, names }) => {
            expect(Object.keys(surface).sort()).toEqual([...names].sort());
        },
    );
});

