// Row 8 package falsifiers: the verifier's roster and ratchet arms, each planted.

import { describe, expect, it } from "vitest";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { runVerifierProbe } from "./exports";

describe("Row 8 package falsifiers", () => {
    it("keeps the required peer and CSS manifest contract", () => {
        const manifest = JSON.parse(readFileSync("package.json", "utf8"));
        const lock = JSON.parse(readFileSync("package-lock.json", "utf8"));
        expect(manifest.peerDependencies["@mkbabb/keyframes.js"]).toBe("^6.0.0");
        expect(manifest.peerDependenciesMeta).not.toHaveProperty("@mkbabb/keyframes.js");
        // [2026-08-25] The pencil peer is RETIRED: the hand voice derives its own
        // geometry from five closed-form laws, so the one subpath that named this peer
        // no longer has anything to resolve. The assertion inverts — a peer that comes
        // back is a peer nobody consumes.
        expect(manifest.peerDependencies).not.toHaveProperty("@mkbabb/pencil-boil");
        expect(manifest.peerDependenciesMeta).not.toHaveProperty("@mkbabb/pencil-boil");
        expect(manifest.devDependencies).not.toHaveProperty("@mkbabb/pencil-boil");
        expect(lock.packages[""]["peerDependencies"]).not.toHaveProperty("@mkbabb/pencil-boil");
        // The exact devDep pin, the registry `resolved` URL, and the sha512
        // integrity are REMEMBERED LITERALS — the very class this row's verifier
        // comment condemns. A routine dev bump or a mirror re-resolve REDs them
        // with zero semantic change. The structural contract is what binds: a
        // caret peer range, its optionality, and lock/manifest agreement (asserted
        // whole in the next case).
        expect(manifest.peerDependenciesMeta["@mkbabb/value.js"]).toEqual({ optional: true });
        expect(manifest.exports["./styles.css"]).toBe("./dist/component-styles.css");
    });

    it("keeps package and lock root metadata in exact agreement", () => {
        const manifest = JSON.parse(readFileSync("package.json", "utf8"));
        const lock = JSON.parse(readFileSync("package-lock.json", "utf8"));
        const lockRoot = lock.packages[""];
        for (const field of [
            "name",
            "version",
            "license",
            "engines",
            "workspaces",
            "dependencies",
            "devDependencies",
            "optionalDependencies",
            "peerDependencies",
            "peerDependenciesMeta",
        ]) {
            expect(Object.hasOwn(lockRoot, field)).toBe(Object.hasOwn(manifest, field));
            expect(lockRoot[field]).toEqual(manifest[field]);
        }
    });

    it("rejects an isolated lock-only root mismatch in the existing verifier", () => {
        const fixture = mkdtempSync(resolve(tmpdir(), "glass-package-lock-drift-"));
        try {
            writeFileSync(resolve(fixture, "package.json"), `${JSON.stringify({ name: "fixture", version: "1.0.0" })}\n`);
            writeFileSync(
                resolve(fixture, "package-lock.json"),
                `${JSON.stringify({ packages: { "": { name: "fixture", version: "2.0.0" } } })}\n`,
            );
            const verifier = pathToFileURL(resolve("scripts/package-verify/index.mjs")).href;
            const probe = `
                import { verifyExportTypes } from ${JSON.stringify(verifier)};
                try {
                    verifyExportTypes({ repositoryRoot: process.argv[1], artifactRoot: process.argv[1] });
                    console.log("NO_ERROR");
                } catch (error) {
                    console.log(error.message);
                }
            `;
            expect(runVerifierProbe(probe, fixture)).toContain(
                "package.json/package-lock.json root metadata mismatch: version",
            );
        } finally {
            rmSync(fixture, { recursive: true, force: true });
        }
        // Subprocess probe — verifier module load flakes vitest's 5s default under the full battery.
    }, 30_000);

    // A-1 (O-20): the published `./styles` closure must PARSE, not merely resolve.
    // The walker strips comments with the naive regex `scripts/lib/minify-css.ts:18`
    // names as THE bug, then only chases @import/url — so a stylesheet no consumer's
    // toolchain can read walked through CLEAN. Nine of ten siblings import `./styles`.
    // The plant is the BadString shape: a newline spliced into the `@source "../*.js"`
    // string interior. postcss tolerates it, which is why the two dist-CSS postcss arms
    // (`tests/styles/emitted-utility-vars.test.ts:64`,
    // `tests/styles/backdrop-prefix-normalization.test.ts:141`) cannot see this class —
    // and why they stay load-bearing in the other direction: an unclosed trailing
    // comment throws for postcss and NOT for lightningcss. Neither parser is a superset
    // of the other; pruning either side reopens a hole.
    it("rejects published CSS that does not parse", () => {
        const fixture = mkdtempSync(resolve(tmpdir(), "glass-css-parse-"));
        try {
            const verifier = pathToFileURL(resolve("scripts/package-verify/index.mjs")).href;
            const probe = `
                import { mkdirSync, writeFileSync } from "node:fs";
                import { verifyExportTypes } from ${JSON.stringify(verifier)};
                const root = process.argv[1];
                mkdirSync(root + "/dist/styles", { recursive: true });
                writeFileSync(root + "/package.json", JSON.stringify({
                    name: "fixture",
                    version: "1.0.0",
                    exports: { "./styles": "./dist/styles/index.css" },
                }));
                writeFileSync(root + "/package-lock.json", JSON.stringify({
                    packages: { "": { name: "fixture", version: "1.0.0" } },
                }));
                writeFileSync(root + "/dist/styles/tokens.css", ":root{--probe:1px}");
                const clean = '@layer theme,base,components,utilities;@import "./tokens.css";@source "../*.js";';
                const at = clean.indexOf("/*");
                const planted = clean.slice(0, at) + "/*\\n  the fold block's own prose\\n" + clean.slice(at);
                const attempt = (css) => {
                    writeFileSync(root + "/dist/styles/index.css", css);
                    try {
                        // A synthetic root has no \`.published-roster\` and is not owed
                        // one — this arm plants a CSS parse defect, not a name removal.
                        // Same opt-out the byte ratchet takes for the same reason.
                        const evidence = verifyExportTypes({ repositoryRoot: root, artifactRoot: root + "/dist", allowMissingRatchet: true });
                        return { terminal: "CLEAN", css: evidence.css };
                    } catch (error) {
                        return { terminal: "FAILED", message: error.message };
                    }
                };
                console.log(JSON.stringify({ clean: attempt(clean), planted: attempt(planted) }));
            `;
            const results = JSON.parse(runVerifierProbe(probe, fixture));
            expect(results.clean).toEqual({ terminal: "CLEAN", css: 2 });
            expect(results.planted.terminal).toBe("FAILED");
            expect(results.planted.message).toContain(
                "styles/index.css: published CSS does not parse",
            );
        } finally {
            rmSync(fixture, { recursive: true, force: true });
        }
        // Subprocess probe — verifier module load flakes vitest's 5s default under the full battery.
    }, 30_000);

    it("G-BARREL-EXPLICIT: keeps the root barrel explicit", () => {
        const source = readFileSync("src/index.ts", "utf8");
        expect(source).not.toMatch(/^\s*export\s+\*\s+from/m);
        expect(source).toMatch(/export\s+type\s*\{/);
        expect(source).toMatch(/export\s*\{/);
    });

    it("rejects duplicate and escaping normalized tar members", () => {
        const verifier = pathToFileURL(resolve("scripts/package-verify/pack.mjs")).href;
        const probe = `
            import { normalizeTarMembers } from ${JSON.stringify(verifier)};
            const rejection = (members) => {
                try {
                    normalizeTarMembers(members);
                    return null;
                } catch (error) {
                    return error.message;
                }
            };
            const acceptedMembers = (members) => [...normalizeTarMembers(members)];
            console.log(JSON.stringify({
                normalizedCollision: rejection("package/dist/a.css\\ndist/a.css\\n"),
                exactDuplicate: rejection("package/dist/a.css\\npackage/dist/a.css\\n"),
                parentAlias: rejection("package/dist/index.js\\npackage/dist/x/../index.js\\n"),
                dotAlias: rejection("package/dist/./index.js\\n"),
                rootEscape: rejection("package/../../escape.js\\n"),
                regularAncestorFirst: rejection("package/dist/index.js\\npackage/dist/index.js/payload\\n"),
                regularAncestorLast: rejection("package/dist/index.js/payload\\npackage/dist/index.js\\n"),
                directoryAncestorFirst: rejection("package/dist/index.js/\\npackage/dist/index.js/payload\\n"),
                directoryAncestorLast: rejection("package/dist/index.js/payload\\npackage/dist/index.js/\\n"),
                conflictingKinds: rejection("package/dist/index.js/\\npackage/dist/index.js\\n"),
                packageRootRegularFirst: rejection("package\\npackage/dist/index.js\\n"),
                packageRootRegularLast: rejection("package/dist/index.js\\npackage\\n"),
                packageRootDirectoryFirst: acceptedMembers("package/\\npackage/dist/index.js\\n"),
                packageRootDirectoryLast: acceptedMembers("package/dist/index.js\\npackage/\\n"),
            }));
        `;
        const results = JSON.parse(runVerifierProbe(probe));
        expect(results.normalizedCollision).toMatch(/tar membership is not unique after package normalization/);
        expect(results.exactDuplicate).toMatch(/tar membership is not unique after package normalization/);
        expect(results.parentAlias).toContain('".." path alias');
        expect(results.parentAlias).toContain('"package/dist/x/../index.js"');
        expect(results.dotAlias).toContain('"." path alias');
        expect(results.dotAlias).toContain('"package/dist/./index.js"');
        expect(results.rootEscape).toContain("tar member escapes the package root");
        expect(results.rootEscape).toContain('"package/../../escape.js"');
        expect(results.regularAncestorFirst).toContain("tar member has a non-directory ancestor");
        expect(results.regularAncestorFirst).toContain('"package/dist/index.js"');
        expect(results.regularAncestorFirst).toContain('"package/dist/index.js/payload"');
        expect(results.regularAncestorLast).toBe(results.regularAncestorFirst);
        expect(results.directoryAncestorFirst).toBeNull();
        expect(results.directoryAncestorLast).toBeNull();
        expect(results.conflictingKinds).toContain("tar membership is not unique after package normalization");
        expect(results.conflictingKinds).toContain("(directory)");
        expect(results.conflictingKinds).toContain("(regular)");
        expect(results.packageRootRegularFirst).toContain("tar member has a non-directory package root");
        expect(results.packageRootRegularLast).toBe(results.packageRootRegularFirst);
        expect(results.packageRootDirectoryFirst).toEqual(["dist/index.js"]);
        expect(results.packageRootDirectoryLast).toEqual(["dist/index.js"]);
        // Subprocess probe — verifier module load flakes vitest's 5s default under the full battery.
    }, 30_000);

    // Both directions are a REBIND. A growth was always loud; a shrink used to pass
    // silently, accumulating headroom until the ceiling meant nothing — so the
    // later-coordinate mode now demands the datum move deliberately, in both
    // directions, and only exact equality rides through.
    it("G-BUNDLE-RATCHET: rejects datum±1 — every movement of the datum is a deliberate rebind", () => {
        const fixture = mkdtempSync(resolve(tmpdir(), "glass-ratchet-hostile-"));
        try {
            writeFileSync(resolve(fixture, ".bundle-ratchet"), "1097643\n");
            const verifier = pathToFileURL(resolve("scripts/package-verify/pack.mjs")).href;
            const probe = `
                import { ratchetEvidence } from ${JSON.stringify(verifier)};
                const root = process.argv[1];
                const results = [];
                const attempt = (bytes, options) => {
                    try {
                        return ratchetEvidence(root, bytes, options);
                    } catch (error) {
                        return error.message;
                    }
                };
                results.push(attempt(1097642, { firstAdoption: true }));
                await import("node:fs").then(({ writeFileSync }) => writeFileSync(root + "/.bundle-ratchet", "1097642\\n"));
                results.push(attempt(1097642, { firstAdoption: true }));
                results.push(attempt(1097643));
                results.push(attempt(1097641));
                results.push(attempt(1097642));
                console.log(JSON.stringify(results));
            `;
            const results = JSON.parse(runVerifierProbe(probe, fixture));
            expect(results[0]).toMatch(/first-adoption bundle ratchet requires exact equality/);
            expect(results[1]).toMatchObject({ mode: "first-adoption", equal: true });
            expect(results[2]).toMatch(/bundle ratchet increase forbidden/);
            expect(results[3]).toMatch(/bundle ratchet shrink — rebind down deliberately/);
            expect(results[4]).toMatchObject({ mode: "later-coordinate", equal: true });
        } finally {
            rmSync(fixture, { recursive: true, force: true });
        }
        // Subprocess probe — verifier module load flakes vitest's 5s default under the full battery.
    }, 30_000);

    // The NAME ratchet, hostile the same way. `.bundle-ratchet` pins the package's
    // size; `.published-roster` pins the names it publishes — the `@theme` tokens and
    // the `@utility` classes a consumer reaches by name. It exists because thirteen
    // tokens and three utilities left at 8.0.0 with no MIGRATION row and nothing
    // noticed for two majors.
    //
    // A SHRINK is excused by exactly one thing: a MIGRATION.md removal ROW whose FIRST
    // cell is the departed name. A sentence about the name is not a row, and neither is
    // the name cited in another row's successor cell — the first spelling of this arm
    // tested the whole file for the substring and would have gone silent on most of the
    // live roster. The removal is fine; the SILENCE is the defect. A GROWTH is excused
    // by nothing, and an ABSENT datum throws — same posture as the byte ratchet, and
    // for the same reason.
    it("G-NO-ORPHAN-EXPORT: the published-roster ratchet bites in both directions, and MIGRATION excuses only a shrink", () => {
        const fixture = mkdtempSync(resolve(tmpdir(), "glass-roster-hostile-"));
        try {
            const verifier = pathToFileURL(resolve("scripts/package-verify/roster.mjs")).href;
            const probe = `
                import { writeFileSync } from "node:fs";
                import { rosterRatchetFailures } from ${JSON.stringify(verifier)};
                const root = process.argv[1];
                const datum = ["theme --gone", "theme --kept", "utility kept-util"];
                const write = (name, text) => writeFileSync(root + "/" + name, text);
                const bind = (lines) => write(".published-roster", lines.join("\\n") + "\\n");
                const results = [];
                const attempt = (roster, options) => {
                    try {
                        return rosterRatchetFailures(root, roster, options);
                    } catch (error) {
                        return error.message;
                    }
                };
                // 0 · no datum at all — a synthetic root is not this repo. An absent
                //     datum THROWS, the way the byte ratchet's does; the caller has to
                //     ask for the armless read.
                results.push(attempt(["theme --kept"]));
                results.push(attempt(["theme --kept"], { allowMissingRatchet: true }).status);
                bind(datum);
                write("MIGRATION.md", "nothing relevant here\\n");
                // 2 · a name left the roster and MIGRATION is silent
                results.push(attempt(["theme --kept", "utility kept-util"]).failures);
                // 3 · the same shrink, now carrying a real removal ROW
                write("MIGRATION.md", "| \`--gone\` | removed 8.0.0 |\\n");
                results.push(attempt(["theme --kept", "utility kept-util"]).failures);
                // 4 · prose that MENTIONS the name — a sentence about it, and another
                //     row citing it as a successor — is not a row, and excuses nothing
                write("MIGRATION.md", "The token --gone was removed at 8.0.0.\\n\\n| \`--other\` | use \`--gone\` instead |\\n");
                results.push(attempt(["theme --kept", "utility kept-util"]).failures);
                // 5 · a GROWTH, which MIGRATION does not excuse
                results.push(attempt([...datum, "utility brand-new"]).failures);
                // 6..8 · byte discipline on the datum itself
                bind(["theme --b", "theme --a"]);
                results.push(attempt(["theme --a", "theme --b"]));
                write(".published-roster", "theme --a\\ntheme --a\\n");
                results.push(attempt(["theme --a"]));
                write(".published-roster", "theme --a");
                results.push(attempt(["theme --a"]));
                console.log(JSON.stringify(results));
            `;
            const results = JSON.parse(runVerifierProbe(probe, fixture));
            expect(results[0]).toMatch(/\.published-roster is missing/);
            expect(results[1]).toBe("ABSENT");
            expect(results[2]).toHaveLength(1);
            expect(results[2][0]).toMatch(
                /left the emitted roster with no MIGRATION\.md row: theme --gone/,
            );
            expect(results[3]).toEqual([]);
            expect(results[4]).toHaveLength(1);
            expect(results[4][0]).toMatch(/no MIGRATION\.md row: theme --gone/);
            expect(results[5]).toHaveLength(1);
            expect(results[5][0]).toMatch(
                /not in the datum — rebind deliberately: utility brand-new/,
            );
            expect(results[6]).toMatch(/\.published-roster is not sorted/);
            expect(results[7]).toMatch(/\.published-roster carries a duplicate/);
            expect(results[8]).toMatch(/\.published-roster must end in exactly one LF/);
        } finally {
            rmSync(fixture, { recursive: true, force: true });
        }
        // Both roster arms spawn a node subprocess that imports the verifier, which
        // pulls in `typescript` and `lightningcss` — seconds of module load before a
        // line of this file's own work runs. Under the whole battery that overruns
        // vitest's 5s default, so the budget is stated rather than inherited (the
        // house idiom: `tests/composables/dark/no-flash.test.ts`'s
        // config-loading arms carry the same explicit 30s).
    }, 30_000);

    // The datum this repo actually ships is bound to the emitted roster, and the
    // committed pair agrees — the same equality the byte ratchet asserts, on names.
    // Driven through the verifier's own staged path (a subprocess, like every probe
    // here), so what it measures is exactly what `npm run verify:package` measures.
    it("G-NO-ORPHAN-EXPORT: the committed .published-roster equals the emitted roster", () => {
        expect(existsSync("dist"), "dist/ is absent — run `npm run build` first").toBe(true);
        const verifier = pathToFileURL(resolve("scripts/package-verify/index.mjs")).href;
        const probe = `
            import { verifyExportTypes } from ${JSON.stringify(verifier)};
            console.log(JSON.stringify(verifyExportTypes({}).roster));
        `;
        const roster = JSON.parse(runVerifierProbe(probe));
        expect(roster.status).toBe("PRESENT");
        expect(roster.datum).toBeGreaterThan(200);
        expect(roster.emitted).toBe(roster.datum);
    }, 30_000);
});

