// G-NO-FLASH: the parse-time stamp's precedence, determinism and write-back, and the stamp plugin in both vite configs. The host rig is in ./host.ts.

import { createHash } from "node:crypto";
import { resolve } from "node:path";
import { runInNewContext } from "node:vm";
import { loadConfigFromFile, type Plugin } from "vite";
import { describe, expect, it } from "vitest";
import { DARK_MODE_STORAGE_KEY, darkModeSyncScript, type DarkModeSyncScriptOptions } from "@glass/composables/dark";
import { type RunOptions, makeHost, runScript } from "./host";

// The no-globals surface, measured where a leak can actually land: `node:vm` runs
// the emitted string with the seeded host AS the run's global object, exactly as
// an inline `<head>` script runs with `window` as its global. An unqualified
// assignment therefore shows up as a NEW own key of `host` — the true detector.
function runInPageGlobal(opts: RunOptions) {
    const { root, writes, host } = makeHost(opts);
    const seeded = new Set(Object.keys(host));
    runInNewContext(darkModeSyncScript(opts.options), host);
    return {
        ...root,
        writes,
        leaked: Object.keys(host).filter((k) => !seeded.has(k)),
    };
}

// BK Lane β unit β0 — the close-battery arms for the seated MOTION gate G-NO-FLASH,
// on its parse-time half. `tests/styles/route-motion/alpha.test.ts` holds the same seat's route-grammar
// arms; these are the FIRST-PAINT arms, and they govern the three seams the
// `DarkModeSyncScriptOptions` addition opens.
//
// SEATS +0 — `G-NO-FLASH` is an already-seated MOTION name (§B.5) and these file as
// close-battery rows under it, exactly as #29's 27 arms did. No seat is minted, no
// `SEAT-BINDING.json` row moves, and the register receipt is byte-identical.
//
// TWO BEHAVIOURS ARE **RATIFIED HERE, NOT INHERITED SILENTLY**, and each has its own
// arm so a later reader cannot mistake them for accidents:
//   1. `normalize` runs AFTER `queryOverride`, so a `?dark` visit PERSISTS into the
//      visitor's own storage. That order is what makes a forced capture survive
//      hydration (the runtime composable re-reads storage and would otherwise flip the
//      page back); it also means the pair is for capture profiles, never for a shared
//      user-facing origin. MIGRATION §8.1.0 states the consequence.
//   2. The query flags are PRESENCE flags — `q.has("dark")`, value-blind — so
//      `?dark=false` resolves DARK. A value grammar would be a second, weaker way to
//      say what `?light` already says.
describe("G-NO-FLASH — the parse-time stamp: precedence, determinism, write-back", () => {
    it("G-NO-FLASH · precedence is query > storage > default, in both directions", () => {
        const options = { queryOverride: true };
        // `?dark` over a stored `light`, under a light platform: nothing but the query
        // can produce dark here.
        const forcedDark = runScript({
            stored: "light",
            prefersDark: false,
            startDark: false,
            search: "?dark",
            options,
        });
        expect(forcedDark.classList.has("dark")).toBe(true);
        expect(forcedDark.style.colorScheme).toBe("dark");

        // `?light` over a stored `dark`, under a dark platform: the mirror.
        const forcedLight = runScript({
            stored: "dark",
            prefersDark: true,
            startDark: true,
            search: "?light",
            options,
        });
        expect(forcedLight.classList.has("dark")).toBe(false);
        expect(forcedLight.style.colorScheme).toBe("light");

        // storage still outranks the default when no query asks
        const stored = runScript({
            stored: "dark",
            prefersDark: false,
            startDark: false,
            search: "",
            options,
        });
        expect(stored.classList.has("dark")).toBe(true);
    });

    it("G-NO-FLASH · a boolean defaultDark is DETERMINISTIC — the platform is not asked", () => {
        // The byte-level half: a boolean answers, so the emitted script carries no
        // media query at all. This is the arm a document that must not flip with the
        // projector's OS theme depends on.
        expect(darkModeSyncScript({ defaultDark: false })).not.toContain("matchMedia");
        expect(darkModeSyncScript({ defaultDark: true })).not.toContain("matchMedia");
        expect(darkModeSyncScript()).toContain("(prefers-color-scheme: dark)");

        // The behavioural half: absent storage under a DARK platform still resolves
        // light when the default says so, and the converse.
        const light = runScript({
            stored: null,
            prefersDark: true,
            startDark: true,
            options: { defaultDark: false },
        });
        expect(light.classList.has("dark")).toBe(false);

        const dark = runScript({
            stored: "auto",
            prefersDark: false,
            startDark: false,
            options: { defaultDark: true },
        });
        expect(dark.classList.has("dark")).toBe(true);
    });

    it("G-NO-FLASH · normalize writes the RESOLVED mode back, so `auto` cannot mean two things", () => {
        const resolved = runScript({
            stored: "auto",
            prefersDark: true,
            startDark: false,
            options: { normalize: true },
        });
        expect(resolved.classList.has("dark")).toBe(true);
        expect(resolved.writes).toEqual([[DARK_MODE_STORAGE_KEY, "dark"]]);

        // the custom key travels into the write-back, not just the read
        const custom = runScript({
            stored: null,
            prefersDark: false,
            startDark: true,
            options: { normalize: true, storageKey: "my-theme" },
        });
        expect(custom.writes).toEqual([["my-theme", "light"]]);
    });

    it("G-NO-FLASH · RATIFIED — normalize runs AFTER the query, so a forced visit PERSISTS", () => {
        // The decision, executable: `?dark` + `normalize` writes "dark" over a stored
        // "light". Reversing the two arms would leave storage saying "light" while the
        // stamp says dark, and the runtime composable would flip the page at hydration
        // — the exact flash this seat exists to forbid. Enable the pair on a capture
        // profile, never on a shared user-facing origin.
        const visit = runScript({
            stored: "light",
            prefersDark: false,
            startDark: false,
            search: "?dark",
            options: { queryOverride: true, normalize: true },
        });
        expect(visit.classList.has("dark")).toBe(true);
        expect(visit.writes).toEqual([[DARK_MODE_STORAGE_KEY, "dark"]]);
    });

    it("G-NO-FLASH · RATIFIED — the query flags are PRESENCE flags, so `?dark=false` reads DARK", () => {
        const options = { queryOverride: true };
        // value-blind by construction: `q.has("dark")` asks whether the key is there.
        for (const search of ["?dark", "?dark=false", "?dark=0", "?dark=light"]) {
            expect(runScript({
                stored: "light",
                prefersDark: false,
                startDark: false,
                search,
                options,
            }).classList.has("dark")).toBe(true);
        }
        // and when both flags are present, `dark` is read first and wins
        expect(runScript({
            stored: "light",
            prefersDark: false,
            startDark: false,
            search: "?light&dark",
            options,
        }).classList.has("dark")).toBe(true);
    });

    it("G-NO-FLASH · the three seams are OPT-IN — the default emission reads no query and writes nothing", () => {
        const out = darkModeSyncScript();
        expect(out).not.toContain("URLSearchParams");
        expect(out).not.toContain("setItem");

        const plain = runScript({
            stored: "auto",
            prefersDark: true,
            startDark: false,
            search: "?light",
        });
        // the query is not read, so the platform still decides
        expect(plain.classList.has("dark")).toBe(true);
        expect(plain.writes).toEqual([]);
    });

    it("G-NO-FLASH · the DEFAULT emission is byte-identical — a CSP hash does not silently re-pin", () => {
        // An inline `<head>` script is what `script-src 'sha256-…'` pins. If the
        // default emission's bytes move, every such consumer's stamp is BLOCKED at
        // first paint — no type error, no runtime error, just the flash this module
        // exists to remove. So the default is pinned to the byte, and both figures
        // below are DERIVED from this function rather than typed: they reproduce the
        // pre-addition emission exactly. [2026-09-22 · register-wave N-3: moved once, at
        // the 10.0.0 major, by the read's inner `try` — 300 B `VTba/T+6…` → 313 B
        // `MOGEZdbx…`. The pin holds the new bytes the same way.]
        const out = darkModeSyncScript();
        expect(Buffer.byteLength(out)).toBe(313);
        expect(createHash("sha256").update(out).digest("base64")).toBe(
            "MOGEZdbxrYiPCsQApEdoFKYoqnbmCxzBPrGPG/EbfJk=",
        );
    });

    it("G-NO-FLASH · no-globals — the emitted body is ONE IIFE and leaks no name", () => {
        // All three seams on, so every emitted arm's declarations are in the run.
        const options: DarkModeSyncScriptOptions = {
            queryOverride: true,
            normalize: true,
            defaultDark: false,
        };
        const out = darkModeSyncScript(options);
        expect(out.startsWith("(function(){")).toBe(true);
        expect(out.endsWith("})();")).toBe(true);

        // MEASURED on the surface a leak can actually reach: `runInPageGlobal`
        // makes the seeded host the run's OWN global, so an unqualified assignment
        // inside the emitted script is a new own key. (A `with(scope)` run cannot
        // see this — a sloppy assignment skips the scope object and lands on the
        // caller's global, which is why that runner does not measure leakage.)
        const run = runInPageGlobal({
            stored: null,
            prefersDark: false,
            startDark: false,
            search: "?dark",
            options,
        });
        // …and the run is not vacuous: `defaultDark:false` + no stored value means
        // ONLY the query arm can produce dark, and the normalize arm then writes it.
        expect(run.classList.has("dark")).toBe(true);
        expect(run.writes).toEqual([[DARK_MODE_STORAGE_KEY, "dark"]]);

        expect(run.leaked).toEqual([]);
    });

    it("G-NO-FLASH · a storage that THROWS ON WRITE never costs the stamp — default AND normalize", () => {
        // The emitted `catch(_){}` swallows, so everything emitted after a throwing
        // call is skipped. That makes the ORDER of the write-back a first-paint
        // contract, not a stylistic choice: with the write emitted before the stamp,
        // `{normalize:true}` paid for a failed write with the whole theme and the page
        // painted unthemed — a page that asked for MORE determinism getting the flash
        // the default is immune to. Measured on the emission, both arms.
        const host = { stored: "auto", prefersDark: true, startDark: false, throwOnWrite: true };

        // The default never reaches `setItem` at all — it is the control, and it is
        // the behaviour the module's prose has always promised.
        const plain = runScript(host);
        expect(plain.classList.has("dark")).toBe(true);
        expect(plain.style.colorScheme).toBe("dark");

        // The arm that does write: the write is LOST (nothing recorded, the throw was
        // swallowed) and the stamp survives it.
        const normalized = runScript({ ...host, options: { normalize: true } });
        expect(normalized.classList.has("dark")).toBe(true);
        expect(normalized.style.colorScheme).toBe("dark");
        expect(normalized.writes).toEqual([]);

        // and with every seam on, so the query arm cannot reintroduce the ordering
        const all = runScript({
            ...host,
            stored: "light",
            prefersDark: false,
            search: "?dark",
            options: { queryOverride: true, normalize: true, defaultDark: false },
        });
        expect(all.classList.has("dark")).toBe(true);
        expect(all.style.colorScheme).toBe("dark");
    });

    it("G-NO-FLASH · a storage that THROWS ON READ still stamps — the default arm paints", () => {
        // The read is the first storage touch, so before 10.0.0 a throwing accessor
        // skipped the whole body inside the one `try` and the page painted unstamped
        // (dark=false, colorScheme=""), measured on 9.0.0. The read now has its own
        // `try`: an unreadable store is treated as absent, and the fallback decides.
        const host = { stored: "dark", startDark: false, throwOnRead: true };

        // "os" asks the platform, in both directions — never the stored "dark"
        for (const prefersDark of [true, false]) {
            const run = runScript({ ...host, prefersDark });
            expect(run.classList.has("dark")).toBe(prefersDark);
            expect(run.style.colorScheme).toBe(prefersDark ? "dark" : "light");
        }

        // the object form takes its ABSENT arm — dark here — not its `auto` arm (light)
        // and not the platform (light): nothing could be read, so no one chose
        const split = runScript({
            ...host,
            prefersDark: false,
            options: { defaultDark: { absent: true, auto: false } },
        });
        expect(split.classList.has("dark")).toBe(true);
        expect(split.style.colorScheme).toBe("dark");

        // normalize: the write-back throws too, after the stamp, and costs only itself
        const normalized = runScript({ ...host, prefersDark: true, options: { normalize: true } });
        expect(normalized.classList.has("dark")).toBe(true);
        expect(normalized.style.colorScheme).toBe("dark");
        expect(normalized.writes).toEqual([]);
    });

    it("G-NO-FLASH · the absent and `auto` arms SPLIT — one object says what no scalar can", () => {
        // The split policy, stated as the pair it is: a first visit is a deliberate
        // light document, a reader who chose `auto` gets their platform. Four repos
        // hand-roll a `<head>` block for want of it (DECK-RELOCATION.md:31).
        const split: DarkModeSyncScriptOptions = {
            defaultDark: { absent: false, auto: "os" },
        };
        const seen = (options: DarkModeSyncScriptOptions, stored: string | null) =>
            runScript({ stored, prefersDark: true, startDark: false, options }).classList.has(
                "dark",
            );

        expect(seen(split, "auto")).toBe(true); // the reader chose the platform
        expect(seen(split, null)).toBe(false); // nobody chose — the document decides

        // EXHAUSTIVE on the scalar spellings: none of them reproduces that pair, which
        // is the whole reason the object form exists rather than a fifth scalar.
        const scalars: DarkModeSyncScriptOptions[] = [
            {},
            { defaultDark: false },
            { defaultDark: true },
            { defaultDark: "os" },
        ];
        for (const options of scalars) {
            expect(seen(options, "auto") && !seen(options, null)).toBe(false);
        }

        // the mirror object, so the split is a real parameter and not one hard-coded pair
        const mirror: DarkModeSyncScriptOptions = {
            defaultDark: { absent: "os", auto: false },
        };
        expect(seen(mirror, "auto")).toBe(false);
        expect(seen(mirror, null)).toBe(true);

        // both arms emit a parseable body, and the object form leaks no name either
        expect(() => new Function(darkModeSyncScript(split))).not.toThrow();
        expect(
            runInPageGlobal({
                stored: "auto",
                prefersDark: true,
                startDark: false,
                options: split,
            }).leaked,
        ).toEqual([]);

        // …and the scalar emissions did not move a byte to gain it [2026-09-22 ·
        // register-wave N-3: the 10.0.0 read hardening spells the absent test `m==null`,
        // so an unreadable store counts as absent; the scalar arm is still one welded test]
        expect(darkModeSyncScript({ defaultDark: false })).toContain(
            '((m==null||m==="auto")&&false)',
        );
    });

    it(
        "G-NO-FLASH · glass-ui's OWN demo stamps at parse time — vite.config.ts injects it first in <head>",
        async () => {
            // The delivery half. A `<head>` script cannot be imported, so the recipe is
            // a build-time injection — and until this plugin existed the library's own
            // shell had no parse-time stamp at all (`index.html` carries no classList,
            // no color-scheme, no localStorage; `demo/main.ts` resolved the theme after
            // the module graph loaded). This reads the REAL config file through vite's
            // own loader, so it measures what `npm run dev` serves.
            // `process.cwd()` is the vitest root and the house idiom — happy-dom
            // leaves `import.meta.url` non-file (token-hygiene.test.ts:41).
            const loaded = await loadConfigFromFile(
                { command: "serve", mode: "development" },
                resolve(process.cwd(), "vite.config.ts"),
            );
            // Flattened as `unknown[]`: vite's own `PluginOption` is a recursive
            // array type, and `.flat(Infinity)` over it costs TS2589.
            const plugins = ((loaded?.config.plugins ?? []) as unknown[]).flat(
                Infinity,
            ) as Plugin[];
            const stamp = plugins.find((p) => p?.name === "glass-ui:dark-mode-stamp");
            expect(stamp, "vite.config.ts carries the dark-mode stamp plugin").toBeTruthy();

            const hook = stamp?.transformIndexHtml;
            const handler = (typeof hook === "function" ? hook : hook?.handler) as unknown as (
                html: string,
                ctx: unknown,
            ) => Array<{ tag: string; children?: string; injectTo?: string }>;
            const tags = await handler("<html><head></head><body></body></html>", {});

            expect(tags).toHaveLength(1);
            expect(tags[0].tag).toBe("script");
            // `head-prepend`: before the icon link, before any stylesheet, before the
            // module — the position is the entire point of a parse-time stamp.
            expect(tags[0].injectTo).toBe("head-prepend");
            // the EMITTED bytes, not a transcription of them (sci-report transcribed;
            // that is the failure this recipe exists to end)
            expect(tags[0].children).toBe(darkModeSyncScript());
            expect(tags[0].children).toContain("localStorage.getItem");
