const ancestorAtRules = (rule: Rule): AtRule[] => {
    const chain: AtRule[] = [];
    let node: Rule["parent"] = rule.parent;
    while (node) {
        if (node.type === "atrule") chain.push(node as AtRule);
        node = (node as { parent?: Rule["parent"] }).parent;
    }
