import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { describe, expect, it } from "vitest";

import { libraryEntryMap } from "../../scripts/structure/index.mjs";

const REPO_ROOT = process.cwd();
const SRC = join(REPO_ROOT, "src");

const CODE_RE = /\.(ts|vue|mts|mjs)$/;

function walk(dir: string, out: string[] = [], slots = false): string[] {
    for (const entry of readdirSync(dir)) {
        const full = join(dir, entry);
        if (statSync(full).isDirectory()) { if (slots || entry !== "__tests__") walk(full, out, slots); }
        else if (CODE_RE.test(entry) && !entry.endsWith(".d.ts")) out.push(full);
    }
    return out;
}

const srcFiles = walk(SRC);
const censusFiles = [
    ...srcFiles,
    ...walk(join(REPO_ROOT, "demo")),
    ...walk(join(REPO_ROOT, "tests")),
    ...walk(SRC, [], true).filter((f) => f.includes("/__tests__/")),
    ...walk(join(REPO_ROOT, "scripts")),
];
